'use strict';
// A small home is one save document; it is stored under the signed-in player's account.
const HOME_VERSION=1;
const cropTypes={radish:{name:'月光萝卜',icon:'crop-radish-3.png',visits:2,yield:3},bell:{name:'星铃花',icon:'crop-bell-3.png',visits:3,yield:2}};
const freshHome=()=>({version:HOME_VERSION,night:1,wood:8,stone:4,star:2,radish:0,bell:0,house:0,workshop:0,garden:0,plots:[null,null],harvested:0,expeditions:0,blessing:false});
let home=freshHome(),homeReady=false,saveRevision=null,savePending=false,saveRunning=false,saveConflict=false,saveFailed=false;
let homeClock=0,nearby=null,toastUntil=0,returnPoint=null;
const homeMap=new Image();homeMap.src='home-map.png';
const homeImages={};for(const name of ['radish','bell'])for(let stage=0;stage<4;stage++){const im=new Image();im.src=`crop-${name}-${stage}.png`;homeImages[`${name}-${stage}`]=im}
for(const name of ['plot','plot-upgraded','wood','stone']){const im=new Image();im.src=`home-${name}.png`;homeImages[name]=im}
const plotLocations=[{x:246,y:214,w:98,h:72},{x:358,y:214,w:100,h:72},{x:246,y:270,w:98,h:40},{x:358,y:270,w:100,h:40}];
const places=[{id:'house',x:179,y:146,label:'温暖小屋',action:'查看小屋'},{id:'well',x:102,y:223,label:'月泉水井',action:'取水歇一歇'},{id:'workshop',x:456,y:132,label:'工作台',action:'制作与扩建'},{id:'bench',x:546,y:248,label:'休息花园',action:'坐下休息'},{id:'gate',x:320,y:338,label:'森林入口',action:'出发探险'}];
// Ground-foot collisions, not the whole sprite rectangle.
const homeSolids=[{x:111,y:0,w:141,h:133},{x:383,y:38,w:163,h:79},{x:75,y:155,w:64,h:57},{x:517,y:193,w:73,h:42}];
function showToast(message){$('#toast').textContent=message;$('#toast').classList.add('show');toastUntil=homeClock+3;sound(580,.055)}
function syncSaveLabel(){const e=$('#save-status');e.classList.toggle('error',saveFailed||saveConflict);e.textContent=saveConflict?'另一个页面已更新 · 点此读取':saveFailed?'保存未完成 · 点此重试':savePending||saveRunning?'正在保存…':homeReady?'家园已保存':'正在读取家园…'}
function persistHome(){savePending=true;syncSaveLabel();void flushHomeSave()}
async function flushHomeSave(){if(saveRunning||saveConflict||!homeReady)return;saveRunning=true;saveFailed=false;syncSaveLabel();try{while(savePending){const snapshot=JSON.stringify(home);savePending=false;const res=await fetch('/api/home',{method:'PUT',headers:{'Content-Type':'application/json',...(saveRevision?{'If-Match':saveRevision}:{'If-None-Match':'*'})},body:snapshot});if(res.status===409){saveConflict=true;savePending=true;throw Error('conflict')}if(!res.ok){savePending=true;throw Error('save')}saveRevision=res.headers.get('ETag');}}catch{saveFailed=true;savePending=true;}finally{saveRunning=false;syncSaveLabel()}}
async function loadHome(){mode='loading';modal('<div class="eyebrow">NOCT · HOME</div><h2>家里的灯还亮着</h2><p>正在打开你的林间家园…</p>');try{const res=await fetch('/api/home',{cache:'no-store'});if(!res.ok)throw Error('load');const data=await res.json();home=data||freshHome();saveRevision=res.headers.get('ETag');await Promise.all([homeMap,foxArt,standArt,...Object.values(homeImages)].map(im=>im.decode?im.decode():Promise.resolve()));homeReady=true;savePending=false;saveFailed=false;saveConflict=false;enterHome();syncSaveLabel();if(!data)persistHome();}catch{modal('<h2>暂时没能打开家园</h2><p>存档还在原处。请重试连接。</p><button class="primary" id="retry">重新打开</button>');$('#retry').onclick=loadHome;}}
function enterHome(){reset();state.zone='home';Object.assign(state.p,{x:301,y:149,inv:0});mode='play';keys.clear();release();$('#overlay').classList.add('hidden');$('#stage').classList.add('home-scene');updateHUD();updateHomePrompt();}
function closeHomeDialog(){mode='play';keys.clear();release();$('#overlay').classList.add('hidden');if(returnPoint){Object.assign(state.p,returnPoint);returnPoint=null}updateHUD();updateHomePrompt();canvas.focus?.();}
function homeDialog(title,body,buttons=[]){mode='home-dialog';keys.clear();release();modal(`<div class="eyebrow">NOCT · 林间家园</div><h2>${title}</h2>${body}<div class="dialog-actions">${buttons.map((b,i)=>`<button ${b.primary?'class="primary"':''} id="home-action-${i}" ${b.disabled?'disabled':''}>${b.label}</button>`).join('')}<button id="close-home">回到院子</button></div>`);buttons.forEach((b,i)=>$('#home-action-'+i).onclick=b.run);$('#close-home').onclick=closeHomeDialog;$('#panel').focus?.();}
function canPay(cost){return Object.entries(cost).every(([key,n])=>home[key]>=n)}
function pay(cost){if(!canPay(cost))return false;for(const [key,n]of Object.entries(cost))home[key]-=n;return true}
const costText=c=>Object.entries(c).map(([k,v])=>({wood:'木材',stone:'石材',star:'星光',radish:'萝卜',bell:'星铃花'}[k]+' '+v)).join(' · ');
function finishChange(message){persistHome();closeHomeDialog();showToast(message);}
function openPlot(index){const crop=home.plots[index],location=plotLocations[index];
 if(!crop){homeDialog(`第 ${index+1} 块菜地`,'<p>选一颗种子，种下今晚的小期待。<br>种子免费，探险归来后成长。</p>'+Object.entries(cropTypes).map(([key,c])=>`<button class="choice" data-crop="${key}"><img class="crop-icon" src="${c.icon}" alt=""><span class="copy">${c.name}<small>${c.visits} 次有效探险后成熟 · 收获 ${c.yield} 份</small></span><span>播种</span></button>`).join(''));document.querySelectorAll('[data-crop]').forEach(b=>b.onclick=()=>{home.plots[index]={type:b.dataset.crop,growth:0};finishChange('种下了'+cropTypes[b.dataset.crop].name);burst(location.x,location.y,'#bfe9d6',12)});return;}
 const c=cropTypes[crop.type],ready=crop.growth>=c.visits;
 homeDialog(c.name,`<p>${ready?'已经成熟了，带着小篮子来收获吧。':`再完成 ${c.visits-crop.growth} 次有效探险，就能收获。<br>留在家里、暂时离开，都不会枯萎。`}</p><div class="progress-row">${Array.from({length:c.visits+1},(_,i)=>`<span class="${i<=crop.growth?'done':''}"></span>`).join('')}</div><p class="note">每次探险至少 30 秒，归来推进一次成长。</p>`,ready?[{label:`收获 ${c.yield} 份`,primary:true,run:()=>{home[crop.type]+=c.yield;home.harvested+=c.yield;home.plots[index]=null;finishChange('收获 '+c.name+' ×'+c.yield);burst(location.x,location.y,'#f7dea4',16)}}]:[]);
}
function openHouse(){const cost={wood:12,stone:6};homeDialog(home.house?'温暖的小屋':'等你修好的小屋',home.house?'<p>门廊和屋顶都修好了，窗子透出暖暖的光。<br>小屋的祝福：下次探险生命上限 +1。</p>':`<p>小屋已经可以遮风，窗边还有几处漏风。<br>修好它，让夜晚住得更舒服。</p><p class="cost">${costText(cost)}</p>`,home.house?[]:[{label:canPay(cost)?'修缮小屋':'材料还不够',primary:true,disabled:!canPay(cost),run:()=>{if(pay(cost)){home.house=1;finishChange('小屋修好了 · 探险生命上限 +1')}}}]);}
function openWorkshop(){const choices=[];
 if(home.plots.length<4)choices.push({title:'再开两块菜地',desc:'院子里增加两块可种植的菜地',cost:{wood:10,stone:4},run:()=>home.plots.push(null,null)});
 if(!home.workshop)choices.push({title:'修整工作台',desc:'制作月光护符 · 探险星光伤害 +1',cost:{wood:8,stone:5,star:4},run:()=>home.workshop=1});
 if(!home.garden)choices.push({title:'布置休息花园',desc:'种上星铃花 · 菜地换上浅色花边',cost:{wood:6,bell:2},run:()=>home.garden=1});
 homeDialog('工作台与储物',`<p>${choices.length?'把森林带回来的礼物，变成家园的一部分。':'院子已经焕然一新。继续种植，攒下新的期待。'}</p>`+choices.map((c,i)=>`<button class="choice" data-build="${i}" ${canPay(c.cost)?'':'disabled'}><span class="copy">${c.title}<small>${c.desc}<br><span class="cost">${costText(c.cost)}</span></small></span></button>`).join(''));
 document.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>{const c=choices[+b.dataset.build];if(pay(c.cost)){c.run();finishChange(c.title+'完成')}});
}
function openBench(){homeDialog('在花园坐一会儿',`<p>听听树叶，看看家里的灯。<br>${home.blessing?'你已经吃过热汤，下次探险会带上这份温暖。':'用 2 份月光萝卜，煮一碗暖汤。'}<br>暖汤：下次探险额外增加 1 点生命。</p><p class="note">篮子里有 ${home.radish} 份萝卜 · ${home.bell} 份星铃花</p>`,[{label:'安静休息',run:()=>{closeHomeDialog();showToast('夜风很轻，家园会一直等你。')}},...(!home.blessing?[{label:'煮一碗暖汤',primary:true,disabled:home.radish<2,run:()=>{if(pay({radish:2})){home.blessing=true;finishChange('喝下暖汤 · 下次探险生命 +1')}}}]:[])]);}
function openGate(){homeDialog('去森林走一走',`<p>探险最长 3 分钟，自动释放星光。<br>靠近木材和石材拾取，带回来建设家园。<br>至少探索 30 秒，归来后作物长大一次。</p><p class="note">小屋 ${home.house?'生命 +1':'尚未修缮'} · 工作台 ${home.workshop?'伤害 +1':'尚未修整'}${home.blessing?' · 暖汤生命 +1':''}<br>途中可以提前回家，已拾取的材料都会保留。</p>`,[{label:'带上星光出发',primary:true,run:()=>start()}]);}
function openJournal(){if(!homeReady||mode==='end'||mode==='loading')return;if(state.zone!=='home'){pause();return;}homeDialog('家园手账',`<div class="journal-grid"><div>家里的夜晚<strong>第 ${home.night} 夜</strong></div><div>森林足迹<strong>${home.expeditions} 次归来</strong></div><div>收获篮子<strong>萝卜 ${home.radish} · 花 ${home.bell}</strong></div><div>家园成长<strong>${home.house+home.workshop+home.garden+(home.plots.length===4?1:0)} / 4 项建设</strong></div></div><p class="note">先播种，再去森林带回木材、石材和星光。<br>存档随账号保存；正在进行的探险在归来时结算。</p>`);}
function interactHome(){if(mode!=='play'||!homeReady)return;if(state.zone!=='home'){openReturn();return}if(!nearby)return;if(nearby.id.startsWith('plot'))openPlot(nearby.index);else({house:openHouse,workshop:openWorkshop,bench:openBench,gate:openGate,well:()=>homeDialog('月泉水井','<p>水壶装满了。播种时会自动浇好水。<br>不用反复浇水，安心去森林走走吧。</p>')})[nearby.id]?.();}
function nearbyObjects(){return [...places,...home.plots.map((crop,i)=>({id:'plot'+i,index:i,x:plotLocations[i].x,y:plotLocations[i].y,label:crop?cropTypes[crop.type].name:'空菜地',action:crop?(crop.growth>=cropTypes[crop.type].visits?'收获作物':'看看作物'):'选择种子'}))]}
function updateHomePrompt(){if(!homeReady)return;const p=state.p,foot={x:p.x,y:p.y+12};nearby=null;let best=68;for(const item of nearbyObjects()){const d=dist(item,foot);if(d<best){best=d;nearby=item}}$('#interact').disabled=!nearby;$('#interact').textContent=nearby?nearby.action+' · E':'靠近物品互动';$('#area-label').textContent=nearby?nearby.label:'林间家园';$('#objective').textContent=nearby?({house:home.house?'灯亮着，家就在这里。':'修好小屋，让夜晚暖一点。',gate:'三分钟探险，捡些材料就回家。',well:'种下的植物会自动浇水。',bench:'坐下来，给自己留一点空闲。',workshop:'用收集的材料慢慢扩建。'}[nearby.id]||'播种、等待探险归来，然后收获。'):(home.plots.some(c=>!c)?'走到菜地旁，种下第一份期待。':'作物在等你，沿小路去森林走走。');}
function blockedHome(x,y){const footY=y+12;if(x<55||x>585||footY<107||footY>348||footY>310&&(x<282||x>365))return true;if(home.plots.some((_,i)=>{const r=plotLocations[i];return x+5>r.x-r.w/2+4&&x-5<r.x+r.w/2-4&&footY+2>r.y-r.h/2+5&&footY-3<r.y+r.h/2-5}))return true;return homeSolids.some(r=>x+7>r.x&&x-7<r.x+r.w&&footY+2>r.y&&footY-3<r.y+r.h)}
function tickHome(dt){const p=state.p;homeClock+=dt;p.animTime+=dt;let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(joy){dx=joy.dx;dy=joy.dy}const norm=Math.max(1,Math.hypot(dx,dy));dx/=norm;dy/=norm;const x=p.x,y=p.y,nx=x+dx*p.speed*dt,ny=y+dy*p.speed*dt;if(!blockedHome(nx,y))p.x=nx;if(!blockedHome(p.x,ny))p.y=ny;updateNoctMotion(p,dt,Math.hypot(p.x-x,p.y-y),dx,dy);for(const a of state.particles){a.x+=a.vx*dt;a.y+=a.vy*dt;a.life-=dt}state.particles=state.particles.filter(a=>a.life>0);if(homeClock>toastUntil)$('#toast').classList.remove('show');updateHomePrompt();}
function sprite(name,x,y,w,h){const im=homeImages[name];if(im?.complete&&im.naturalWidth)ctx.drawImage(im,Math.round(x),Math.round(y),w,h)}
function drawHome(){ctx.fillStyle='#344963';ctx.fillRect(0,0,W,H);if(homeMap.complete&&homeMap.naturalWidth)ctx.drawImage(homeMap,0,0,W,H);
 if(home.house){glow(178,95,44,'rgba(255,207,135,.23)');glow(207,102,26,'rgba(255,213,150,.19)')}
 if(home.workshop){glow(462,96,25,'rgba(161,226,239,.24)');sprite('bell-3',458,86,15,17)}
 const sorted=[];if(home.house){for(const [x,y]of [[150,135],[206,136]])sorted.push({y,draw:()=>sprite('bell-3',x-9,y-20,18,22)})}
 home.plots.forEach((c,i)=>{const loc=plotLocations[i];if(i>=2||home.garden)sprite(home.garden?'plot-upgraded':'plot',loc.x-loc.w/2,loc.y-loc.h/2,loc.w,loc.h);if(c){const spec=cropTypes[c.type],stage=c.growth>=spec.visits?3:c.growth===0?0:c.growth===1?1:2;for(let row=0;row<2;row++)for(let col=0;col<3;col++){const x=loc.x+(col-1)*25,y=loc.y-(i>=2?8:13)+row*(i>=2?16:29);sorted.push({y,draw:()=>sprite(`${c.type}-${stage}`,x-14,y-29,28,30)})}if(c.growth>=spec.visits){const b=Math.floor(homeClock*2)%2;rect(loc.x+38,loc.y-31-b,2,5,'#f5dda7');rect(loc.x+36,loc.y-29-b,6,1,'#fff0c1')}}});
 if(home.garden){for(const [x,y]of [[514,250],[553,254],[569,250],[496,249]])sorted.push({y,draw:()=>sprite('bell-3',x-10,y-22,20,24)})}
 sorted.push({y:state.p.y+12,draw:()=>drawFox(state.p,state)});sorted.sort((a,b)=>a.y-b.y).forEach(item=>item.draw());
 for(let i=0;i<8;i++){const x=66+(i*79)%510+Math.sin(homeClock*.6+i)*7,y=140+(i*41)%206+Math.cos(homeClock*.45+i)*5;ctx.globalAlpha=.3+(.5+.5*Math.sin(homeClock*2+i))*.4;rect(x,y,1,1,'#d0f5d5')}ctx.globalAlpha=1;
 for(const a of state.particles)rect(a.x,a.y,2,2,a.c);
 if(nearby&&mode==='play'){const y=nearby.y-37+Math.round(Math.sin(homeClock*3));ctx.fillStyle='#21304ee8';ctx.fillRect(nearby.x-8,y-8,16,13);ctx.strokeStyle='#c6dacc';ctx.strokeRect(nearby.x-8,y-8,16,13);ctx.fillStyle='#f6ead1';ctx.font='9px sans-serif';ctx.textAlign='center';ctx.fillText('E',nearby.x,y+2)}
}
const originalStart=start,originalHUD=updateHUD,originalPause=pause;
start=function(){if(!homeReady)return;const usedBlessing=home.blessing;keys.clear();release();originalStart();state.zone='forest';state.loot={wood:0,stone:0,star:0};state.collected=0;state.p.max+=home.house+(usedBlessing?1:0);state.p.hp=state.p.max;state.damage+=home.workshop;state.homeStats={house:home.house,workshop:home.workshop,soup:usedBlessing};home.blessing=false;persistHome();state.nodes=Array.from({length:16},(_,i)=>({x:80+(i*137)%475,y:80+(i*89)%260,type:i%3===0?'stone':'wood',active:true}));$('#stage').classList.remove('home-scene');$('#toast').classList.remove('show');updateHUD();};
function tickForestGather(){for(const n of state.nodes||[]){if(n.active&&dist(n,state.p)<22){n.active=false;state.loot[n.type]+=n.type==='wood'?3:2;burst(n.x,n.y,n.type==='wood'?'#dac094':'#a9cbdc');sound(360,.04)}}}
function drawForestGather(){for(const n of state.nodes||[])if(n.active)sprite(n.type,n.x-10,n.y-10,20,20)}
function openReturn(){if(mode!=='play'||state.zone!=='forest')return;mode='return';keys.clear();release();modal(`<h2>沿着星光回家</h2><p>已经拾取的材料都会带回家。<br>${state.time>=30?'作物会在这次归来后长大一次。':`再探索 ${Math.ceil(30-state.time)} 秒，归来时作物才会成长。`}</p><div class="dialog-actions"><button id="stay">再走一会儿</button><button class="primary" id="go-home">现在回家</button></div>`);$('#stay').onclick=()=>{mode='play';$('#overlay').classList.add('hidden')};$('#go-home').onclick=()=>end(false,true);}
end=function(win,early=false){if(state.settled)return;state.settled=true;keys.clear();release();const loot=state.loot||{wood:0,stone:0,star:0},grew=state.time>=30;if(win){loot.wood+=4;loot.stone+=2;loot.star+=3}for(const key of ['wood','stone','star'])home[key]+=loot[key];if(grew){home.night++;home.expeditions++;for(const c of home.plots)if(c)c.growth=Math.min(cropTypes[c.type].visits,c.growth+1)}persistHome();mode='end';modal(`<div class="eyebrow">NOCT · 欢迎回家</div><h2>${win?'带着晨光归来':early?'今天就走到这里':'星光带你回家了'}</h2><p>探索 ${Math.floor(state.time)} 秒 · 击退 ${state.kills} 个黑影<br><span class="cost">木材 +${loot.wood} · 石材 +${loot.stone} · 星光 +${loot.star}</span><br>${grew?'院子里的作物长大了一点。':'本次不足 30 秒，作物暂未成长。'}</p><button class="primary" id="return-home">回到小院</button>`);$('#return-home').onclick=enterHome;updateHUD();};
updateHUD=function(){originalHUD();if(!homeReady)return;for(const key of ['wood','stone','star'])$('#'+key).textContent=home[key];$('.chapter').textContent=(state.zone==='home'?'林间家园':'森林探险')+' · 第 '+home.night+' 夜';$('#journal').disabled=!['play','home-dialog','pause'].includes(mode);if(state.zone==='home'){$('#kills').textContent='慢慢建设，不会枯萎';$('#controls').textContent='WASD / 方向键移动 · E 互动 · 空格暂停';}else{$('#area-label').textContent='森林探险';$('#objective').textContent=`背包：木材 ${state.loot?.wood||0} · 石材 ${state.loot?.stone||0} · 星光 ${state.loot?.star||0}`;$('#interact').disabled=mode!=='play';$('#interact').textContent='提前回家';$('#controls').textContent='WASD 移动 · 自动攻击 · 靠近材料拾取';}$('#pause').textContent=mode==='pause'?'继续 ▷':'暂停 Ⅱ';};
const buildLabels={damage:'闪耀吊坠',haste:'急促星光',speed:'轻盈脚步',magnet:'星光引力',vitality:'温暖余烬',flames:'环绕鬼火'};
function valueNumber(n,digits=0){return String(parseFloat(Number(n).toFixed(digits)))}
function statCard(name,value,detail){return `<div class="stat-card"><span>${name}</span><strong>${value}</strong><small>${detail}</small></div>`}
function forestStatsHTML(){const p=state.p,builds=Object.entries(state.builds||{}).filter(([,n])=>n>0),bonuses=[];
 if(state.homeStats?.house)bonuses.push('温暖小屋 · 生命 +1');if(state.homeStats?.workshop)bonuses.push('修整工作台 · 伤害 +1');if(state.homeStats?.soup)bonuses.push('暖汤 · 生命 +1');
 return `<div class="eyebrow">NOCT · 本次探险</div><div class="stats-title"><h2>当前属性</h2><span>LV. ${state.lv}</span></div><div class="stats-grid">${statCard('生命',`${p.hp} / ${p.max}`,'受到伤害归零则提前回家')}${statCard('星光伤害',valueNumber(state.damage),'每颗自动星光的伤害')}${statCard('施放频率',valueNumber(1/state.rate,2)+' / 秒','自动攻击的出手速度')}${statCard('移动速度',Math.round(p.speed/78*100)+'%','相对初始脚步速度')}${statCard('拾取范围',Math.round(state.magnet/28*100)+'%','星光自动靠近的距离')}${statCard('环绕鬼火',state.flames+' 团','接触黑影造成伤害')}</div><div class="run-meta"><span>经验 ${state.xp} / ${state.need}</span><span>击退 ${state.kills}</span><span>探索 ${Math.floor(state.time/60)}:${String(Math.floor(state.time%60)).padStart(2,'0')}</span></div><div class="build-summary"><h3>本次 Build</h3><div class="build-chips">${builds.length?builds.map(([key,n])=>`<span>${buildLabels[key]} ×${n}</span>`).join(''):'<em>尚未获得局内强化</em>'}</div>${bonuses.length?`<h3>出发加成</h3><div class="build-chips permanent">${bonuses.map(x=>`<span>${x}</span>`).join('')}</div>`:''}</div><div class="pause-loot">背包　木材 ${state.loot?.wood||0}　石材 ${state.loot?.stone||0}　星光 ${state.loot?.star||0}</div><button class="primary" id="resume">继续探险</button>`}
function homeStatsHTML(){const nextHp=5+home.house+(home.blessing?1:0),nextDamage=1+home.workshop;return `<div class="eyebrow">NOCT · 林间家园</div><div class="stats-title"><h2>下一次出发</h2><span>第 ${home.night} 夜</span></div><div class="stats-grid compact">${statCard('最大生命',nextHp,home.house||home.blessing?'包含家园与食物加成':'当前基础属性')}${statCard('星光伤害',nextDamage,home.workshop?'工作台永久强化 +1':'当前基础属性')}${statCard('移动速度','100%','局内可以继续强化')}${statCard('拾取范围','100%','局内可以继续强化')}</div><div class="build-summary"><h3>已准备的加成</h3><div class="build-chips permanent">${[home.house&&'温暖小屋 · 生命 +1',home.workshop&&'修整工作台 · 伤害 +1',home.blessing&&'暖汤 · 下次生命 +1'].filter(Boolean).map(x=>`<span>${x}</span>`).join('')||'<em>靠近建筑准备下一次探险</em>'}</div></div><button class="primary" id="resume">回到院子</button>`}
pause=function(){if(mode==='home-dialog'){closeHomeDialog();return}if(mode==='return'){mode='play';$('#overlay').classList.add('hidden');return}if(mode==='play'){mode='pause';keys.clear();release();modal(state.zone==='home'?homeStatsHTML():forestStatsHTML());$('#resume').onclick=pause;updateHUD();return}if(mode==='pause'){mode='play';$('#overlay').classList.add('hidden');keys.clear();release();updateHUD();}};
$('#interact').onclick=interactHome;$('#journal').onclick=openJournal;$('#pause').onclick=pause;$('#save-status').onclick=()=>{if(saveConflict){homeDialog('另一个页面更新了家园','<p>为避免覆盖那边的进度，请读取最新存档。<br>当前页面尚未保存的变化会被替换。</p>',[{label:'读取最新家园',primary:true,run:loadHome}]);}else if(saveFailed)void flushHomeSave()};
window.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='e'&&!e.repeat&&e.target?.tagName!=='BUTTON'){e.preventDefault();interactHome()}});
window.addEventListener('beforeunload',e=>{if(savePending||saveRunning){e.preventDefault();e.returnValue=''}});
window.addEventListener('online',()=>{if(savePending&&!saveConflict)void flushHomeSave()});
void loadHome();
